// Flatten the extractor output into the flat snake_case record the Risebird webhook expects,
// and repair the two fields the gate and the MAG assignment depend on.
function text(value) {
  return value === undefined || value === null ? '' : String(value).trim();
}

// The Naukri subject line has a fixed shape:
//   'NVite - Naukri.com -Risebird Online Interviewer - {MAG}, {role}, {company}, ...'
// Relay documented the 'Online Interviewer-{MAG}' form; both the bare hyphen and the
// hyphen-with-spaces occur, so accept either and stop at the first comma. Parsing this here
// is more reliable than asking the model to do it, and mag_name drives MAG assignment.
function magFromSubject(subject) {
  const match = String(subject || '').match(/Online\s+Interviewer\s*[-\u2013\u2014:]\s*([^,]+)/i);
  const mag = match ? match[1].trim() : '';
  return mag.length > 0 && mag.length <= 120 ? mag : '';
}

// '17 Years & 0 Months' -> 17. Only used when the model returns nothing usable.
function yearsFromSubject(subject) {
  const match = String(subject || '').match(/(\d{1,2})\s*\+?\s*Years?/i);
  return match ? Number(match[1]) : 0;
}

function wholeYears(value) {
  const number = Number(text(value).replace(/[^\d.]/g, ''));
  return Number.isFinite(number) ? Math.floor(number) : 0;
}

// Naukri puts the candidate's name in the From display name, which is a dependable fallback
// when extraction comes back empty.
function nameFromSender(from) {
  const match = String(from || '').match(/^\s*"?([^"<]+?)"?\s*<[^>]*>\s*$/);
  const name = match ? match[1].trim() : '';
  return name && !name.includes('@') ? name : '';
}

const sources = $('Build AI Input').all();
const items = $input.all();
const out = [];

for (let i = 0; i < items.length; i++) {
  const context = ((sources[i] || {}).json) || {};
  const extracted = (((items[i] || {}).json) || {}).output || {};

  const subject = text(context.subject);
  const modelYears = wholeYears(extracted.experience_years);
  const years = modelYears > 0 ? modelYears : yearsFromSubject(subject);

  const candidateEmail = text(extracted.candidate_email).toLowerCase();

  out.push({
    json: {
      message_id: text(context.message_id),
      sender_email: text(context.from_email),
      subject,
      mail_content: text(context.body_excerpt),
      received_at: text(context.received_at),
      attachment_count: Number(context.attachment_count || 0),

      candidate_name: text(extracted.candidate_name) || nameFromSender(context.from),
      location: text(extracted.location),
      past_experience: text(extracted.past_experience),
      notice_period: text(extracted.notice_period),
      education: text(extracted.education),
      key_skills: text(extracted.key_skills),
      current_role: text(extracted.current_role),
      experience_years: String(years),
      experience_years_num: years,
      salary: text(extracted.salary),
      mag_name: magFromSubject(subject) || text(extracted.mag_name),
      // Guard against the model echoing the Naukri notification address back at us.
      candidate_email: candidateEmail.endsWith('@naukri.com') ? '' : candidateEmail,
      candidate_phone: text(extracted.candidate_phone).replace(/[^\d+]/g, '')
    }
  });
}

return out;

// Carry the candidate record into the search step (the HTTP node replaces json with the
// SerpAPI response, so the record has to be recoverable by index afterwards) and build the
// query Relay used: name + current role + location, restricted to LinkedIn profile URLs.
const out = [];

for (const item of $input.all()) {
  const record = { ...(item.json || {}) };

  const terms = [record.candidate_name, record.current_role, record.location]
    .map((value) => String(value || '').trim())
    .filter(Boolean)
    .join(' ');

  record.linkedin_query = `${terms} site:linkedin.com/in`.trim();
  out.push({ json: record });
}

return out;

// Recover the candidate record and render the search hits as compact text. A failed or empty
// search is not fatal: the verifier is told so explicitly and answers NO, which is the same
// verdict Relay produced when its search returned nothing.
const MAX_RESULTS = 10;

const sources = $('Prepare LinkedIn Query').all();
const responses = $input.all();
const out = [];

for (let i = 0; i < responses.length; i++) {
  const record = { ...(((sources[i] || {}).json) || {}) };
  const response = ((responses[i] || {}).json) || {};
  const results = Array.isArray(response.organic_results) ? response.organic_results : [];

  const lines = results.slice(0, MAX_RESULTS).map((result, index) => {
    const title = String((result && result.title) || '').trim();
    const link = String((result && result.link) || '').trim();
    const snippet = String((result && result.snippet) || '').replace(/\s+/g, ' ').trim();
    return `${index + 1}. ${title}\n   ${link}\n   ${snippet}`;
  });

  record.search_result_count = lines.length;
  record.search_results_text = lines.length
    ? lines.join('\n')
    : 'NO SEARCH RESULTS AVAILABLE.';

  out.push({ json: record });
}

return out;

