  "type": "object",
  "properties": {
    "linkedin_match": { "type": "string", "enum": ["YES", "NO"], "description": "YES only when a search result is clearly this same person's LinkedIn profile." },
    "confidence": { "type": "integer", "description": "Calibrated certainty in the decision, 0-100." },
    "linkedin_url": { "type": "string", "description": "The matched linkedin.com/in URL, or 'None' when there is no match." },
