parameters.jsCode:
// Attach the verdict to the record. A missing verdict — model error, or a search that never
// ran — degrades to an explicit NO rather than dropping the candidate: the prospect still has
// to reach the portal so an operator can pick it up.
const sources = $('Prepare LinkedIn Input').all();
const verdicts = $input.all();
const out = [];

for (let i = 0; i < verdicts.length; i++) {
  const record = { ...(((sources[i] || {}).json) || {}) };
  const verdict = (((verdicts[i] || {}).json) || {}).output || {};

  const match = String(verdict.linkedin_match || '').trim().toUpperCase() === 'YES' ? 'YES' : 'NO';
  const url = String(verdict.linkedin_url || '').trim();
  const confidence = Number(verdict.confidence);

  record.linkedin_match = match;
  record.linkedin_url = match === 'YES' && url && url.toLowerCase() !== 'none' ? url : 'None';
  record.linkedin_confidence = Number.isFinite(confidence)
    ? Math.max(0, Math.min(100, Math.round(confidence)))
    : 0;
  record.linkedin_reason = String(verdict.reason || '').trim()
    || (Number(record.search_result_count || 0) === 0
      ? 'No LinkedIn search results were available for this candidate.'
      : 'The verification model returned no verdict.');

  out.push({ json: record });
}

return out;

// One item per attachment, pulled back off the trigger by message id so that a poll carrying
// several emails never mixes one candidate's resume into another's record.
const triggerByMessageId = new Map();
for (const item of $('Gmail Trigger').all()) {
  triggerByMessageId.set(String((item.json || {}).id || ''), item);
}

// Relay named the uploaded file '{candidate_name} - {mag_name} - Resume'. Keep that so the
// Drive folder stays browsable, but retain the original extension so the file still opens.
function driveName(record, originalName) {
  const dot = originalName.lastIndexOf('.');
  const extension = dot > 0 ? originalName.slice(dot) : '';
  const label = [record.candidate_name, record.mag_name]
    .map((value) => String(value || '').trim())
    .filter(Boolean)
    .join(' - ');
  return (label ? `${label} - Resume${extension}` : originalName).replace(/[\\/:*?"<>|]/g, '_');
}

const out = [];

for (const item of $input.all()) {
  const record = item.json || {};
  const messageId = String(record.message_id || '');
  const trigger = triggerByMessageId.get(messageId);
  const binary = (trigger && trigger.binary) || {};

  for (const key of Object.keys(binary)) {
    if (!key.startsWith('attachment_')) continue;
    const file = binary[key];
    const originalName = file.fileName || key;
    out.push({
      json: {
        message_id: messageId,
        file_name: originalName,
        drive_name: driveName(record, originalName)
      },
      binary: { data: file }
    });
  }
}

return out;

// Collapse the per-attachment uploads back to one item per email. Relay created a single
// prospect from the first uploaded file, so the first link wins here too — and, unlike Relay,
// a mail carrying two attachments can no longer create two prospect records.
const uploads = $('Upload Resume to Drive').all();
const sources = $('Split Attachments').all();

const linksByMessageId = new Map();

for (let i = 0; i < uploads.length; i++) {
  const file = ((uploads[i] || {}).json) || {};
  const messageId = String((((sources[i] || {}).json) || {}).message_id || '');
  const link = file.webViewLink || (file.id ? `https://drive.google.com/file/d/${file.id}/view` : '');
  if (!link) continue;
  if (!linksByMessageId.has(messageId)) linksByMessageId.set(messageId, []);
  linksByMessageId.get(messageId).push(link);
}

const out = [];

for (const item of $('Merge LinkedIn Verdict').all()) {
  const record = { ...(item.json || {}) };

  // Mirrors the IF condition, so an email is never dropped just because Drive returned no
  // usable link for it.
  if (Number(record.attachment_count || 0) <= 0) continue;

  const links = linksByMessageId.get(String(record.message_id || '')) || [];
  record.resume_link = links[0] || '';
  record.resume_links = links;

  out.push({ json: record });
}

return out;

// Single convergence point for both branches, so the webhook payload is always built from one
// identical record shape.
const out = [];

for (const item of $input.all()) {
  const record = { ...(item.json || {}) };

  record.resume_link = String(record.resume_link || '').trim() || 'None';
  record.has_attachment = Number(record.attachment_count || 0) > 0;
  record.source = 'n8n';

  out.push({ json: record });
}

return out;
